def solve(h1, h2, h3, h4):
    # 计算每个整点时刻时针与分针的夹角（取小于180度的角）
    def get_angle(h):
        h = int(h)
        deg = h * 30
        if deg > 180:
            deg = 360 - deg
        return deg

    angles = {
        '①': get_angle(h1),
        '②': get_angle(h2),
        '③': get_angle(h3),
        '④': get_angle(h4)
    }

    labels = ['①', '②', '③', '④']

    # 1. 找最大的角 (Constraints ensure unique max)
    max_val = max(angles.values())
    max_labels = [k for k, v in angles.items() if v == max_val]
    ans1 = max_labels[0]

    # 2. 找相等的角 (Constraints ensure exactly one pair)
    equal_pairs = []
    for i in range(len(labels)):
        for j in range(i+1, len(labels)):
            if angles[labels[i]] == angles[labels[j]]:
                equal_pairs.append((labels[i], labels[j]))

    if equal_pairs:
        ans2_1, ans2_2 = equal_pairs[0]
    else:
        ans2_1, ans2_2 = "", ""

    # 3. 比较图②和图④ (Constraints ensure they are not equal)
    ang2 = angles['②']
    ang4 = angles['④']
    if ang2 > ang4:
        ans3 = "大"
    else:
        ans3 = "小"

    return [ans1, ans2_1, ans2_2, ans3]

