def solve(color, target_id, r1, r2, r3, r4):
    from fractions import Fraction
    def to_frac(s):
        if isinstance(s, Fraction):
            return s
        if '/' in str(s):
            n, d = str(s).split('/')
            return Fraction(int(n), int(d))
        return Fraction(s)

