def solve(context, time_labels, values, q1_text, q2_text):
    val_list = [Decimal(v.strip()) for v in values.split(',')]
    time_list = [t.strip() for t in time_labels.split(',')]

    ans1 = ""
    if "整体呈现什么变化趋势" in q1_text:
        if val_list[-1] > val_list[0]:
            ans1 = "上升"
        elif val_list[-1] < val_list[0]:
            ans1 = "下降"
        else:
            ans1 = "平稳"

    elif "变化幅度最大" in q1_text:
        max_diff = Decimal('-1')
        max_idx = 0
        for i in range(len(val_list) - 1):
            diff = abs(val_list[i+1] - val_list[i])
            if diff > max_diff:
                max_diff = diff
                max_idx = i
        ans1 = f"{time_list[max_idx]}到{time_list[max_idx+1]}"

    elif "平均数值" in q1_text:
        total = sum(val_list)
        avg = total / len(val_list)
        ans1 = str(avg.quantize(Decimal('0.1')))

    ans2 = ""
    if "中间时刻" in q2_text:
        mid_idx = len(val_list) // 2
        v = val_list[mid_idx]
        if v % 1 == 0:
            ans2 = str(int(v))
        else:
            ans2 = str(v)

    elif "最大值的一半" in q2_text:
        max_val = max(val_list)
        target = max_val / Decimal('2')
        min_dist = abs(val_list[0] - target)
        best_idx = 0
        for i, v in enumerate(val_list):
            dist = abs(v - target)
            if dist < min_dist:
                min_dist = dist
                best_idx = i
        ans2 = time_list[best_idx]

    elif "快还是慢" in q2_text:
        last_diff = abs(val_list[-1] - val_list[-2])
        first_diff = abs(val_list[1] - val_list[0])
        if last_diff > first_diff:
            ans2 = "快"
        elif last_diff < first_diff:
            ans2 = "慢"
        else:
            ans2 = "一样"

    return [ans1, ans2]

def solve(category, percent, amount, entity):
    from decimal import Decimal
    # 已知部分量 amount 和对应的百分比 percent%，求总量
    # 总量 = 部分量 / (百分比 / 100)
    total = Decimal(str(amount)) / (Decimal(str(percent)) / Decimal('100'))
    return int(total)

