def solve(n, items_str, results_str):
    def parse_items(s):
        clean_s = ""
        for char in s:
            if char.isdigit() or char == '个':
                continue
            clean_s += char
        parts = clean_s.split('、')
        return set(p.strip() for p in parts if p.strip())

